def _resume_membership_change(self, name: str) -> None:
    """Finish any change a previous leader left open: if a joint entry is
    committed but no stable entry follows it, append the stable entry now;
    if an add was still catching the learner up, keep driving catch-up."""
    st = self.state[name]
    committed = st.committed_config(self.initial_config)
    latest = st.latest_config(self.initial_config)
    if committed.get("type") == CONFIG_JOINT and latest.get("type") != CONFIG_STABLE:
        joint_entry = None
        # Look first in the uncompacted committed suffix, then through a
        # snapshot's applied history (the joint entry may itself have been
        # compacted).
        upper = min(st.commit_index, st.last_log_index())
        for i in range(st.snapshot_index + 1, upper + 1):
            entry = st.log[i - 1 - st.snapshot_index]
            if entry.get("kind") == KIND_CONFIG and entry["entryType"] == CONFIG_JOINT:
                joint_entry = entry
        if joint_entry is None:
            for applied in reversed(st.applied):
                if (
                    applied.get("kind") == KIND_CONFIG
                    and applied["entryType"] == CONFIG_JOINT
                ):
                    joint_entry = applied
                    break
        if joint_entry is not None:
            _, new_voters = self._config_groups(committed)
            stable = self._stable_config(new_voters)
            stable_entry = self._append_config_entry(
                name,
                joint_entry["id"],
                CONFIG_STABLE,
                stable,
                joint_entry["action"],
                joint_entry["member"],
            )
