    n=len(names)
    order={x:(60+25*i) for i,x in enumerate(names)}
    sc={"nodes":names,"duration":3000,"electionTimeouts":order,
        "heartbeatInterval":40,"messageDelay":rng.choice([0,3,8]),
        "initialMembers":sorted(names[:rng.randint(3,n)]),"membershipChanges":[],
        "faults":[],"clientCommands":[],"nodeEvents":[]}
    if rng.random()<0.7: sc["snapshotThreshold"]=rng.choice([1,2,3])
    voters=set(sc["initialMembers"]); learners=set(names)-voters
    t=200; changes=sc["membershipChanges"]
    crash_state=set()
    for _ in range(rng.randint(3,8)):
        t+=rng.randint(60,200)
        roll=rng.random()
        if roll<0.25:
            # crash a random voter/learner, restart later
            v=rng.choice(names)
            if v not in crash_state:
                sc["nodeEvents"].append({"time":t,"node":v,"action":"crash"}); crash_state.add(v)
                sc["nodeEvents"].append({"time":t+rng.randint(80,300),"node":v,"action":"restart"}); crash_state.discard(v)
        elif roll<0.45:
            rng.shuffle(names); cut=rng.randint(1,n-1)
            sc["faults"].append({"time":t,"action":"partition","groups":[sorted(names[:cut]),sorted(names[cut:])]})
            sc["faults"].append({"time":t+rng.randint(50,250),"action":"heal"})
        elif roll<0.55:
            sc["clientCommands"].append({"time":t,"node":"a","id":f"x{len(sc['clientCommands'])}","command":rng.randint(0,9)})
        else:
            action=rng.choice(["add","remove"])
            if action=="add" and learners:
                member=rng.choice(sorted(learners))
            elif action=="remove" and len(voters)>3:
                member=rng.choice(sorted(voters))
            else:
                continue
            receiver=rng.choice(["a","a","b"])  # sometimes a non-leader
            changes.append({"time":t,"node":receiver,"id":f"m{len(changes)}","action":action,"member":member})
            if receiver=="a" and member in voters and action=="remove" or (action=="add" and member in learners):
                if action=="add": voters.add(member); learners.discard(member)
                else: voters.discard(member); learners.add(member)
    return sc

